async function parseApiResponse(r){
  const text=await r.text();
  const contentType=String(r.headers.get('content-type')||'').toLowerCase();
  let d=null;
  try{d=text?JSON.parse(text):{}}catch(e){
    const looksHtml=/^\s*<!doctype|^\s*<html|<body|<p>There has been a critical error|wordpress\.org\/documentation\/article\/faq-troubleshooting/i.test(text||'');
    const status='HTTP '+r.status;
    if(looksHtml) throw new Error('ERP server returned an HTML error page ('+status+'). No ERP data was changed. The loaded ERP build is '+String(A.build||'unknown')+'. Open System Health and server error logs before retrying.');
    throw new Error(contentType&&!contentType.includes('json')?('ERP server returned a non-JSON response ('+status+'). No ERP data was changed.') : ('ERP server returned invalid JSON ('+status+'). No ERP data was changed.'));
  }
  if(!r.ok)throw new Error((d&&d.message)||(d&&d.code)||('ERP request failed ('+r.status+').'));
  if(d===null||typeof d!=='object')throw new Error('ERP server returned an unexpected response. No ERP data was changed.');
  return d;
}
function resolveTrustedApiUrl(path){
  const raw=/^https?:\/\//i.test(String(path))?String(path):String(A.api||'')+String(path);
  let target;try{target=new URL(raw,window.location.href)}catch(_){throw new Error('ERP request URL is invalid. No ERP data was changed.')}
  const bases=[A.api,A.api_v16].filter(Boolean);
  const allowed=bases.some(function(value){
    let base;try{base=new URL(String(value),window.location.href)}catch(_){return false}
    if(target.origin!==base.origin)return false;
    const routeBase=base.searchParams.get('rest_route');
    const targetRoute=target.searchParams.get('rest_route');
    if(routeBase!==null){const expected=routeBase.replace(/\/+$/,'');return typeof targetRoute==='string'&&(targetRoute===expected||targetRoute.indexOf(expected+'/')===0)}
    const prefix=base.pathname.replace(/\/+$/,'');
    return target.pathname===prefix||target.pathname.indexOf(prefix+'/')===0;
  });
  if(!allowed)throw new Error('Blocked ERP request outside the configured WordPress REST API. No ERP data was changed.');
  return target.href;
}
async function api(path,opt={}){const headers=Object.assign({'X-WP-Nonce':A.nonce},opt.headers||{});const multipart=typeof FormData!=='undefined'&&opt.body instanceof FormData;if(multipart){Object.keys(headers).forEach(k=>{if(k.toLowerCase()==='content-type')delete headers[k]})}else if(!Object.keys(headers).some(k=>k.toLowerCase()==='content-type')){headers['Content-Type']='application/json'}opt.headers=headers;const url=resolveTrustedApiUrl(path);let controller=null;let timer=null;if(!opt.signal){controller=new AbortController();opt.signal=controller.signal;timer=setTimeout(()=>controller.abort(),25000)}if(!opt.cache && (!opt.method || String(opt.method).toUpperCase()==='GET'))opt.cache='no-store';try{return await parseApiResponse(await fetch(url,opt))}catch(e){if(e?.name==='AbortError')throw new Error('ERP request timed out. No ERP data was changed. Please retry after checking System Health.');if(e instanceof TypeError && /failed to fetch/i.test(String(e.message||'')))throw new Error('ERP connection failed. The server could not be reached and no ERP data was changed. Check the ERP URL/hosting connection and retry.');throw e}finally{if(timer)clearTimeout(timer)}}
