    '<div class="sl-panel"><div class="sl-block-head"><h3>Recent branch expenses</h3><small>Operational history</small></div><div class="sl-table-wrap"><table class="sl-table"><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Amount</th><th>Status</th></tr></thead><tbody>'+((expenses.slice(0,30).map(x=>'<tr><td>'+esc(x.expense_date||'')+'</td><td>'+esc(x.category||'')+'</td><td>'+esc(x.description||'')+'</td><td>'+money(x.amount||0)+' + VAT '+money(x.tax_amount||0)+'</td><td><span class="sl-pill ok">'+esc(x.status||'POSTED')+'</span></td></tr>').join(''))||'<tr><td colspan="5">No branch expenses recorded.</td></tr>')+'</tbody></table></div></div></div>';
